import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.BVA38fkC.js";var i=JSON.parse(`{"title":"JavaScript migration plan","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/docs/MIGRATION_PLAN.html"}],["meta",{"property":"og:title","content":"JavaScript migration plan | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/docs/MIGRATION_PLAN.html"}],["meta",{"name":"twitter:title","content":"JavaScript migration plan | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"MIGRATION_PLAN.md","filePath":"MIGRATION_PLAN.md","lastUpdated":1793948159000}`),a={name:`MIGRATION_PLAN.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="javascript-migration-plan" tabindex="-1">JavaScript migration plan <a class="header-anchor" href="#javascript-migration-plan" aria-label="Permalink to “JavaScript migration plan”">​</a></h1><h2 id="runtime-contract" tabindex="-1">Runtime contract <a class="header-anchor" href="#runtime-contract" aria-label="Permalink to “Runtime contract”">​</a></h2><p>One shared JavaScript engine must run unchanged in Node.js and modern browsers. Keep calculation modules free of Node-only APIs, DOM access, and environment-dependent I/O. Adapters handle file loading, terminal output, browser interaction, and report delivery.</p><h2 id="target-layout" tabindex="-1">Target layout <a class="header-anchor" href="#target-layout" aria-label="Permalink to “Target layout”">​</a></h2><p><code>src/</code> contains all application code:</p><ul><li><code>src/core/</code>: financial domain models, validation, dates, interest, cash-flow accounting, events and results.</li><li><code>src/strategies/</code>: shared Greedy, GSS, Absolute R and Absolute R+ strategies plus search algorithms.</li><li><code>src/reporting/</code>: console formatter and standalone HTML report generator.</li><li><code>src/io/</code>: CSV parsing and Node-side data loading.</li><li><code>src/cli/</code>: Node CLI. Supports Greedy, GSS, Absolute R and Absolute R+.</li><li><code>src/web/</code>: GitHub Pages browser application. Exposes Greedy, GSS and Absolute R+ for scoped date-range simulations. Absolute R remains CLI-only. Goal mode is disabled until the Absolute R-only Goal planner is complete.</li><li><code>data/</code>: portable bank and FD product datasets shared by both runtimes.</li><li><code>schema/</code>: configuration JSON Schema.</li><li><code>tests/</code>: engine unit tests, CLI tests and browser-facing contract tests.</li><li><code>archive/</code>: immutable snapshot of the complete tracked Python project at migration baseline.</li></ul><h2 id="non-negotiable-parity-requirements" tabindex="-1">Non-negotiable parity requirements <a class="header-anchor" href="#non-negotiable-parity-requirements" aria-label="Permalink to “Non-negotiable parity requirements”">​</a></h2><ol><li>CLI and web invoke the same strategy and simulation modules; no duplicate strategy implementations.</li><li>Both generate the same canonical report model and use the same HTML report template/generator.</li><li>Preserve account-specific eFD eligibility, transfer channels/fees, AIT treatment, payout schedules, maturity accounting, event ordering, and all existing strategy semantics.</li><li>Preserve the eight-section report, chart interactions, per-event chart stages, bank FD-principal aggregation, and existing colour/line-style rules.</li><li>Preserve CLI diagnostic/printing patterns. Browser presentation may differ, but calculated values and event ordering must not.</li><li>Absolute R is an exhaustive internal verification strategy: CLI and automated tests only. It is not a user-selectable web strategy.</li><li>Use deterministic calculations and explicit numeric tolerances in parity tests. Do not silently round intermediate financial values.</li></ol><h2 id="migration-sequence" tabindex="-1">Migration sequence <a class="header-anchor" href="#migration-sequence" aria-label="Permalink to “Migration sequence”">​</a></h2><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> Preserve complete tracked legacy tree under <code>archive/</code>.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> Port domain models and configuration validation.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> Port interest, AIT, transfer fees, and cash-flow accounting.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> Port simulator and deterministic event ledger.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" disabled="disabled"><label class="task-list-item-label" for="task-item-4"> Port Greedy and establish Python-vs-JavaScript golden fixtures.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-5" disabled="disabled"><label class="task-list-item-label" for="task-item-5"> Port Absolute R+ and validate diagnostics and scoped-objective parity.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-6" disabled="disabled"><label class="task-list-item-label" for="task-item-6"> Retain Absolute R for CLI/internal testing only.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-7" disabled="disabled"><label class="task-list-item-label" for="task-item-7"> Port canonical report model, console output, and standalone HTML report.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-8" disabled="disabled"><label class="task-list-item-label" for="task-item-8"> Build interactive web configuration and results UI (Greedy, GSS and Absolute R+; scoped mode only).</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-9" disabled="disabled"><label class="task-list-item-label" for="task-item-9"> Build CLI (Greedy/GSS/Absolute R+/Absolute R).</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-10" disabled="disabled"><label class="task-list-item-label" for="task-item-10"> Add Node CI, browser tests, and GitHub Pages deployment from <code>main</code>.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-11" disabled="disabled"><label class="task-list-item-label" for="task-item-11"> Merge migration into <code>main</code> after regression and CLI/web report parity pass.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-12" disabled="disabled"><label class="task-list-item-label" for="task-item-12"> Retire feature branches only after their changes are verified in the archived baseline and migration history.</label></li></ul><h2 id="branch-and-release-safety" tabindex="-1">Branch and release safety <a class="header-anchor" href="#branch-and-release-safety" aria-label="Permalink to “Branch and release safety”">​</a></h2><p>Perform structural refactors on a dedicated branch and merge through a reviewed pull request. Do not rewrite <code>main</code> history or modify <code>archive/</code>; keep the shared engine runtime-neutral and verify both CLI and Pages packaging after path changes.</p>`,12)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};